/*
 * fim/test/test_fim_data.c - the FIM module data blocks (source-l2yd)
 *
 * Generated by: Claude Opus 5.5
 *
 * fim/fim_data.c is #included, so the objects under test are the real
 * blocks with the image's contents:
 *
 *   FIM_$DATA        map "D E2126C FIM_ size = 134"
 *   FIM_$WIRED_DATA  the data run 0xE21FE6..0xE2277C of "D E21890 FIM_WIRED"
 *
 * Checked: the image addresses; the offsets that hold on every build (those
 * behind the pointer-bearing eventcounts and handler table are asserted at
 * compile time on the target only); that every per-ASID table has
 * FIM_AS_COUNT elements with asid N at element N; the image contents (frame
 * size table, self-linked eventcounts, quit_inh all 0xFF, zero elsewhere);
 * and - through the real FIM_$INIT_ASID, FIM_$FREE_ASID and
 * FIM_$ACKNOWLEDGE - that the code indexes the tables with the asid.
 */

#include <stdint.h>
#include <stdio.h>
#include <string.h>

/* ==========================================================================
 * Test framework
 * ========================================================================== */

static int tests_failed = 0;
static int tests_run = 0;

#define TEST(name) static void test_##name(void)
#define RUN_TEST(name)                                                        \
    do {                                                                      \
        printf("  Running %s... ", #name);                                    \
        tests_run++;                                                          \
        test_##name();                                                        \
        printf("done\n");                                                     \
    } while (0)

#define ASSERT_EQ(expected, actual)                                           \
    do {                                                                      \
        long long _e = (long long)(expected);                                 \
        long long _a = (long long)(actual);                                   \
        if (_e != _a) {                                                       \
            printf("FAILED\n    Expected: 0x%llx, Got: 0x%llx at line %d\n",  \
                   (unsigned long long)_e, (unsigned long long)_a, __LINE__); \
            tests_failed++;                                                   \
            return;                                                           \
        }                                                                     \
    } while (0)

#include "fim/fim_internal.h"

/* ==========================================================================
 * Mocked callees and foreign cells
 * ========================================================================== */

uint16_t PROC1_$AS_ID;

static int clear_trace_calls;
static int16_t clear_trace_asid;

void (FIM_$CLEAR_TRACE_FAULT)(uint32_t as_id_slot)
{
    int16_t as_id = (int16_t)ARCH_PASCAL_SLOT_WORD(as_id_slot); (void)as_id;
    clear_trace_calls++;
    clear_trace_asid = as_id;
}

static int advance_calls;
static ec_$eventcount_t *advanced;

void EC_$ADVANCE(ec_$eventcount_t *ec)
{
    advance_calls++;
    advanced = ec;
}

/* ==========================================================================
 * Code under test
 * ========================================================================== */

#include "../fim_data.c"
#include "../init_asid.c"
#include "../free_asid.c"
#include "../acknowledge.c"

#define GAP(a, b) ((long long)((const char *)&(b) - (const char *)&(a)))

TEST(block_addresses_and_sizes)
{
    ASSERT_EQ(0x00E2126Cu, MODULE_DATA_ADDR(FIM_$DATA));
    ASSERT_EQ(0x134, FIM_$DATA_SIZE);
    ASSERT_EQ(0x00E213A0u, MODULE_DATA_ADDR(FIM_$DATA) + FIM_$DATA_SIZE); /* FIM_UNWIRED */
    ASSERT_EQ(0x00E21FE6u, MODULE_DATA_ADDR(FIM_$WIRED_DATA));             /* PARITY_$INFO */
    ASSERT_EQ(0x796, FIM_$WIRED_DATA_SIZE);
    ASSERT_EQ(0x00E2277Cu, MODULE_DATA_ADDR(FIM_$WIRED_DATA) + FIM_$WIRED_DATA_SIZE);
    /* map symbols inside the wired run, at the target offsets of fim/fim.h */
    ASSERT_EQ(0x00E21FFAu, MODULE_DATA_ADDR(FIM_$WIRED_DATA) + 0x014);    /* MISS_STATUS */
    ASSERT_EQ(0x00E21FFEu, MODULE_DATA_ADDR(FIM_$WIRED_DATA) + 0x018);    /* PENDING_TRACE_FAULTS */
    ASSERT_EQ(0x00E22002u, MODULE_DATA_ADDR(FIM_$WIRED_DATA) + 0x01C);    /* FIM_$QUIT_EC */
    ASSERT_EQ(0x00E222BAu, MODULE_DATA_ADDR(FIM_$WIRED_DATA) + 0x2D4);    /* FIM_$QUIT_VALUE */
    ASSERT_EQ(0x00E223A2u, MODULE_DATA_ADDR(FIM_$WIRED_DATA) + 0x3BC);    /* FIM_$TRACE_STS */
    ASSERT_EQ(0x00E2248Au, MODULE_DATA_ADDR(FIM_$WIRED_DATA) + 0x4A4);    /* FIM_$QUIT_INH */
    ASSERT_EQ(0x00E224C4u, MODULE_DATA_ADDR(FIM_$WIRED_DATA) + 0x4DE);    /* FIM_$DELIV_EC */
    /* 12-byte eventcounts: quit_ec[57] ends at quit_value, deliv_ec[57] at the block end */
    ASSERT_EQ(0x2D4 - 0x01C, FIM_AS_COUNT * 12);
    ASSERT_EQ(0x796 - 0x4DE, FIM_AS_COUNT * 12);
}

TEST(offsets_every_build)
{
    ASSERT_EQ(0x000, offsetof(fim_$data_t, in_fim));
    ASSERT_EQ(0x000, offsetof(fim_$wired_data_t, parity));
    ASSERT_EQ(0x014, offsetof(fim_$wired_data_t, miss_status));
    ASSERT_EQ(0x018, offsetof(fim_$wired_data_t, pending_trace_faults));
    ASSERT_EQ(0x000, offsetof(parity_state_t, spurious_count));  /* PARITY_$INFO */
}

TEST(asid_n_is_element_n)
{
    unsigned n;

    ASSERT_EQ(FIM_AS_COUNT, sizeof(FIM_$DATA.in_fim));
    ASSERT_EQ(FIM_AS_COUNT, sizeof(FIM_$DATA.user_fim_addr) / sizeof(FIM_$DATA.user_fim_addr[0]));
    ASSERT_EQ(FIM_AS_COUNT, sizeof(FIM_$WIRED_DATA.quit_ec) / sizeof(ec_$eventcount_t));
    ASSERT_EQ(FIM_AS_COUNT, sizeof(FIM_$WIRED_DATA.quit_value) / 4);
    ASSERT_EQ(FIM_AS_COUNT, sizeof(FIM_$WIRED_DATA.trace_sts) / 4);
    ASSERT_EQ(FIM_AS_COUNT, sizeof(FIM_$WIRED_DATA.quit_inh));
    ASSERT_EQ(FIM_AS_COUNT, sizeof(FIM_$WIRED_DATA.deliv_ec) / sizeof(ec_$eventcount_t));

    for (n = 0; n < FIM_AS_COUNT; n++) {
        /* (0,A5,asid), (0,A1,asid) */
        ASSERT_EQ((long long)n, GAP(FIM_$DATA.in_fim[0], FIM_$DATA.in_fim[n]));
        ASSERT_EQ((long long)n, GAP(FIM_$WIRED_DATA.quit_inh[0], FIM_$WIRED_DATA.quit_inh[n]));
        /* (0,A1,asid*4) */
        ASSERT_EQ((long long)n * 4, GAP(FIM_$WIRED_DATA.quit_value[0], FIM_$WIRED_DATA.quit_value[n]));
        ASSERT_EQ((long long)n * 4, GAP(FIM_$WIRED_DATA.trace_sts[0], FIM_$WIRED_DATA.trace_sts[n]));
        /* (0,A0,asid*12): one ec_$eventcount_t, 12 bytes on the target */
        ASSERT_EQ((long long)n * (long long)sizeof(ec_$eventcount_t),
                  GAP(FIM_$WIRED_DATA.quit_ec[0], FIM_$WIRED_DATA.quit_ec[n]));
        ASSERT_EQ((long long)n * (long long)sizeof(ec_$eventcount_t),
                  GAP(FIM_$WIRED_DATA.deliv_ec[0], FIM_$WIRED_DATA.deliv_ec[n]));
        /* (0x3c,A5,asid*4): one handler address per asid */
        ASSERT_EQ((long long)n * (long long)sizeof(void *),
                  GAP(FIM_$DATA.user_fim_addr[0], FIM_$DATA.user_fim_addr[n]));
    }
}

TEST(image_contents)
{
    static const uint8_t frame_size[16] = {
        0x08, 0x08, 0x0C, 0x00, 0x10, 0x00, 0x00, 0x00,
        0x3A, 0x14, 0x20, 0x5C, 0x00, 0x00, 0x00, 0x00,
    };
    unsigned i;

    ASSERT_EQ(0, memcmp(FIM_$DATA.frame_size, frame_size, sizeof(frame_size)));
    ASSERT_EQ(0x3A, fim_get_frame_size(8));
    ASSERT_EQ(0x5C, fim_get_frame_size(0xB));
    ASSERT_EQ(0x00, fim_get_frame_size(3));

    for (i = 0; i < FIM_AS_COUNT; i++) {
        ASSERT_EQ(0, FIM_$DATA.in_fim[i]);
        ASSERT_EQ(0, (uintptr_t)FIM_$DATA.user_fim_addr[i]);
        ASSERT_EQ(0, FIM_$WIRED_DATA.quit_ec[i].value);
        ASSERT_EQ((uintptr_t)&FIM_$WIRED_DATA.quit_ec[i],
                  (uintptr_t)FIM_$WIRED_DATA.quit_ec[i].waiter_list_head);
        ASSERT_EQ((uintptr_t)&FIM_$WIRED_DATA.quit_ec[i],
                  (uintptr_t)FIM_$WIRED_DATA.quit_ec[i].waiter_list_tail);
        ASSERT_EQ(0, FIM_$WIRED_DATA.quit_value[i]);
        ASSERT_EQ(0, FIM_$WIRED_DATA.trace_sts[i]);
        ASSERT_EQ(-1, FIM_$WIRED_DATA.quit_inh[i]);
        ASSERT_EQ(0, FIM_$WIRED_DATA.deliv_ec[i].value);
        ASSERT_EQ((uintptr_t)&FIM_$WIRED_DATA.deliv_ec[i],
                  (uintptr_t)FIM_$WIRED_DATA.deliv_ec[i].waiter_list_head);
        ASSERT_EQ((uintptr_t)&FIM_$WIRED_DATA.deliv_ec[i],
                  (uintptr_t)FIM_$WIRED_DATA.deliv_ec[i].waiter_list_tail);
    }
    ASSERT_EQ(0, FIM_$WIRED_DATA.parity.spurious_count);
    ASSERT_EQ(0, FIM_$WIRED_DATA.parity.err_ppn);
    ASSERT_EQ(0, FIM_$WIRED_DATA.miss_status);
    ASSERT_EQ(0, FIM_$WIRED_DATA.pending_trace_faults);
    ASSERT_EQ(8, FIM_$INITIAL_STACK_SIZE);
}

TEST(routines_index_with_the_asid)
{
    int16_t asid = 57;                  /* the last element of every table */
    static int handler;

    FIM_$WIRED_DATA.quit_ec[57].value = 0x1234;
    FIM_$WIRED_DATA.quit_inh[57] = 0;
    FIM_$WIRED_DATA.quit_value[56] = 0x5555;
    FIM_$DATA.user_fim_addr[57] = &handler;

    FIM_$INIT_ASID(&asid);              /* 0x00E0AA24 */
    ASSERT_EQ(1, clear_trace_calls);
    ASSERT_EQ(57, clear_trace_asid);
    ASSERT_EQ(0x1234, FIM_$WIRED_DATA.quit_value[57]);
    ASSERT_EQ(0x5555, FIM_$WIRED_DATA.quit_value[56]);
    ASSERT_EQ(-1, FIM_$WIRED_DATA.quit_inh[57]);

    PROC1_$AS_ID = 57;
    FIM_$WIRED_DATA.quit_ec[57].value = 0x1235;
    FIM_$ACKNOWLEDGE();                 /* 0x00E0A96C */
    ASSERT_EQ(0x1235, FIM_$WIRED_DATA.quit_value[57]);
    ASSERT_EQ(0, FIM_$WIRED_DATA.quit_inh[57]);
    ASSERT_EQ(1, advance_calls);
    ASSERT_EQ((uintptr_t)&FIM_$WIRED_DATA.deliv_ec[57], (uintptr_t)advanced);

    FIM_$FREE_ASID(&asid);              /* 0x00E0AA6C */
    ASSERT_EQ(2, clear_trace_calls);
    ASSERT_EQ(0, (uintptr_t)FIM_$DATA.user_fim_addr[57]);
    ASSERT_EQ(-1, FIM_$WIRED_DATA.quit_inh[57]);
    ASSERT_EQ(0x5555, FIM_$WIRED_DATA.quit_value[56]);
}

int main(void)
{
    printf("FIM module data tests\n");
    RUN_TEST(block_addresses_and_sizes);
    RUN_TEST(offsets_every_build);
    RUN_TEST(asid_n_is_element_n);
    RUN_TEST(image_contents);
    RUN_TEST(routines_index_with_the_asid);
    printf("%d tests, %d failed\n", tests_run, tests_failed);
    return tests_failed ? 1 : 0;
}
